{{!-- Styling parameters: class, titleClass, gridClass, cardClass, buttonClass, cardTitleClass, descriptionClass, priceClass, benefitsClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Component: Pricing Table | Usage: {{> "components/pricing-table"}} --}}
{{#if @site.members_enabled}}
{{#unless @site.members_invite_only}}
{{#if @site.allow_self_signup}}
<section class="gh-pricing{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Membership plans">
    <h2 class="gh-pricing-title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{#if title}}{{title}}{{else}}Choose your membership{{/if}}</h2>
    <div class="gh-pricing-grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">
    {{#get "tiers" filter="visibility:public+active:true" include="monthly_price,yearly_price,benefits"}}
    {{#foreach tiers}}
        {{#match type "free"}}
        <article class="gh-pricing-card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}">
            <h3 class="gh-pricing-card-title{{#if ghostcnStyles.cardTitleClass}} {{ghostcnStyles.cardTitleClass}}{{/if}}">{{name}}</h3>
            {{#if description}}<p class="gh-pricing-description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{description}}</p>{{/if}}
            <p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}}">Free</p>
            {{#if benefits}}<ul class="gh-pricing-benefits{{#if ghostcnStyles.benefitsClass}} {{ghostcnStyles.benefitsClass}}{{/if}}">{{#foreach benefits}}<li>{{this}}</li>{{/foreach}}</ul>{{/if}}
            {{#if @member}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/account" data-portal="account">Manage account</a>
            {{else}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/signup/free" data-portal="signup/free">Join free</a>{{/if}}
        </article>
        {{else}}
        {{#if @site.paid_members_enabled}}
        <article class="gh-pricing-card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}">
            <h3 class="gh-pricing-card-title{{#if ghostcnStyles.cardTitleClass}} {{ghostcnStyles.cardTitleClass}}{{/if}}">{{name}}</h3>
            {{#if description}}<p class="gh-pricing-description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{description}}</p>{{/if}}
            {{#if benefits}}<ul class="gh-pricing-benefits{{#if ghostcnStyles.benefitsClass}} {{ghostcnStyles.benefitsClass}}{{/if}}">{{#foreach benefits}}<li>{{this}}</li>{{/foreach}}</ul>{{/if}}
            {{#if monthly_price}}<p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}}">{{price monthly_price currency=currency}} <span>/ month</span></p>{{/if}}
            {{#if yearly_price}}<p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}}">{{price yearly_price currency=currency}} <span>/ year</span></p>{{/if}}
            <div class="gh-pricing-actions">
            {{#if @member}}
                <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/account/plans" data-portal="account/plans">{{#if @member.paid}}Manage plan{{else}}Upgrade membership{{/if}}</a>
            {{else}}
                {{#if monthly_price}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup/{{id}}/monthly" data-portal="signup/{{id}}/monthly">Subscribe monthly</a>{{/if}}
                {{#if yearly_price}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/signup/{{id}}/yearly" data-portal="signup/{{id}}/yearly">Subscribe yearly</a>{{/if}}
            {{/if}}
            </div>
        </article>
        {{/if}}
        {{/match}}
    {{/foreach}}
    {{else}}
        <p>Membership plans are currently unavailable.</p>
    {{/get}}
    </div>
</section>
{{/if}}
{{/unless}}
{{/if}}
{{/with}}

/* ghostcn: live membership pricing */
.gh-pricing { box-sizing: border-box; width: min(100% - 2em, 72em); margin: 3em auto; color: var(--foreground); font-size: 16px; line-height: 1.5; }
.gh-pricing *, .gh-pricing *::before, .gh-pricing *::after { box-sizing: border-box; }
.gh-pricing-title { margin: 0 0 1.5em; text-align: center; font-size: 2em; }
.gh-pricing-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 18em), 1fr)); gap: 1.25em; }
.gh-pricing-card { min-width: 0; overflow-wrap: anywhere; display: flex; flex-direction: column; gap: 1em; padding: 1.5em; border: 1px solid var(--border); border-radius: min(var(--radius), 1.5em); background: var(--card); color: var(--card-foreground); }
/* Follow the card's local foreground, not the page's dark/light tokens.
   A custom background must be paired with a readable foreground at the call site. */
.gh-pricing-card-title { margin: 0; font-size: 1.25em; color: inherit; }
.gh-pricing-card p { margin: 0; }
.gh-pricing-description { color: inherit; }
.gh-pricing-benefits { margin: 0; padding-left: 1.25em; color: inherit; }
.gh-pricing-benefits li { color: inherit; }
.gh-pricing-price { font-size: 1.75em; font-weight: 700; color: inherit; }
.gh-pricing-price span { font-size: 0.875em; font-weight: 400; color: inherit; }
.gh-pricing-actions { display: flex; flex-wrap: wrap; gap: 0.5em; margin-top: auto; }
